// A review proposal is an immutable snapshot, independent of explorer rename/delete.
const reviewSource = initialBodies['inspector-tab-visibility.css'];
function chatView() { return `<div class="chat"><div class="user-msg"><div class="msg-head"><b style="color:var(--talos-text)">TU</b><span>Scenario demo</span></div><p>Rivedi File e Agenti nella sidebar destra. Conserva lo stile Talos e lascia che io possa seguire il lavoro senza perdere il contesto.</p></div><div><div class="msg-head"><b>TALOS</b><span>Risposta dimostrativa · nessun modello collegato</span></div><div class="assistant-copy">Parto dai componenti esistenti. La tab attiva e il dettaglio dell’agente devono restare indipendenti: puoi esplorare i file, tornare all’agente e ritrovare il punto in cui eri.</div><div class="toolgroup"><div class="toolrow">${icon('check')}<span class="grow">Riferimenti del design system</span><span class="muted mono">index.css</span></div><div class="toolrow">${icon('branch')}<span class="grow">Ponte delle tab e contenitore del dettaglio</span><span class="badge">Fixture</span></div><div class="toolrow">${icon('shield')}<span class="grow">Modifiche proposte in area isolata</span><button data-action="view" data-value="review" class="small">Vedi Review →</button></div></div><div class="checkpoint"><h3 style="margin-bottom:7px">Un workspace, due punti di vista.</h3><p class="muted">I file mostrano chi li sta leggendo o modificando. Ogni agente porta ai file del suo task e alle differenze da verificare.</p></div></div><div class="toolgroup" style="margin:0"><div class="toolrow"><span class="grow">File → attività → agente</span><button class="btn" data-action="file-agent" data-id="fix">Prova il collegamento</button></div><div class="toolrow"><span class="grow">Grafo operativo della sessione</span><button class="btn" data-action="open-graph">Apri diagramma</button></div></div></div>`; }
function fileView() {
    const s = store.get(), f = fileBy(s.selectedFile);
    if (!f)
        return '<div class="empty"><h2>File non disponibile</h2><p>Seleziona un file presente nel workspace. I file eliminati restano nel cestino.</p></div>';
    const body = bodies[f.id] || `// Fixture locale: ${f.id}\n// Il contenuto del file reale non è caricato in questa pagina.\n\nexport const example = true;`;
    return `<div class="workspace-view"><div class="file-header"><div class="row"><span class="eyebrow grow">Anteprima locale</span><button data-action="favorite" data-id="${esc(f.id)}" aria-pressed="${!!f.favorite}" class="small">${f.favorite ? 'Rimuovi preferito' : 'Preferito'}</button><button class="file-more" aria-haspopup="menu" aria-expanded="false" data-action="file-menu" data-id="${esc(f.id)}" aria-label="Azioni sul file aperto">${icon('more')}</button></div><h3 style="margin-top:8px">${esc(filePath(f))}</h3></div><pre class="source-code" tabindex="0" aria-label="Codice dimostrativo">${body.split('\n').map((l, i) => `<span class="ln">${i + 1}</span>${esc(l)}`).join('\n')}</pre><div class="provenance"><div class="row"><span class="badge accent">Fixture</span><span class="grow">${f.agent ? esc(agents.find(a => a.id === f.agent)?.name) + ' · ' + esc(f.activity) : 'Nessuna attività agente associata'}</span>${f.agent ? `<button class="btn" data-action="file-agent" data-id="${f.agent}">Apri agente</button>` : ''}</div><p class="muted" style="margin-top:8px">La lettura non modifica il workspace. Refactor e Genera test aprono una proposta da rivedere.</p></div></div>`;
}
function graphAgents() { const s = store.get(); let list = agents.filter(a => (s.scope === 'workspace' || a.session === s.session) && (s.scope !== 'execution' || a.run === (s.session === 'sidebar' ? 'r1' : s.session === 'tests' ? 'r4' : 'r3')) && a.born <= graph.time); const hidden = new Set(); function childHide(id) { agents.filter(a => a.parent === id).forEach(a => { if (hidden.has(a.id))
    return; hidden.add(a.id); childHide(a.id); }); } graph.collapsed.forEach(childHide); list = list.filter(a => !hidden.has(a.id)); if (s.graphIsolated)
    list = list.filter(a => a.id === s.graphIsolated); if (graph.query)
    list = list.filter(a => (a.name + ' ' + a.task).toLowerCase().includes(graph.query.toLowerCase())); if (graph.status !== 'all')
    list = list.filter(a => a.status === graph.status); return list; }
function graphView() { const s = store.get(); return `<div class="workspace-view"><div class="view-head"><div class="grow"><div class="eyebrow" style="margin-bottom:6px">Agenti / osservabilità</div><h2>Diagramma della sessione</h2><p>Gerarchie, dipendenze e attività. Dati dimostrativi.</p></div><button data-action="graph-close" class="iconbutton" title="Chiudi il diagramma" aria-label="Chiudi il diagramma">${icon('x')}</button></div><div class="toolbar"><select id="graphScope" aria-label="Ambito del diagramma">${[['execution', 'Esecuzione'], ['session', 'Sessione corrente'], ['workspace', 'Workspace']].map(([v, t]) => `<option value="${v}" ${s.scope === v ? 'selected' : ''}>${t}</option>`).join('')}</select><input id="graphSearch" aria-label="Cerca agente nel diagramma" placeholder="Cerca agente…" value="${esc(graph.query)}" style="flex:1;width:120px"><select id="graphStatus" aria-label="Filtra stato nel diagramma">${[['all', 'Tutti gli stati'], ['active', 'In corso'], ['waiting', 'In attesa'], ['error', 'Errori'], ['done', 'Terminati']].map(([v, t]) => `<option value="${v}" ${graph.status === v ? 'selected' : ''}>${t}</option>`).join('')}</select></div><div class="toolbar"><button class="btn" data-action="fit">Adatta</button><button data-action="zoom-out" aria-label="Riduci zoom">−</button><span id="zoomLabel" class="small mono">${Math.round(graph.zoom * 100)}%</span><button data-action="zoom-in" aria-label="Aumenta zoom">+</button><button data-action="follow" aria-pressed="${graph.follow}" class="${graph.follow ? 'btn' : ''}">Segui attivo</button><button data-action="split" aria-pressed="${graph.split}">Affianca file</button><span class="grow"></span>${s.graphIsolated ? '<button data-action="clear-isolate" class="btn">Esci da isolamento</button>' : ''}</div><div style="position:relative;display:flex;flex:1;min-height:0"><div class="graph-canvas ${graph.split ? 'split' : ''}" id="graphCanvas" tabindex="0" aria-label="Diagramma: trascina per spostare, usa i controlli per lo zoom"><div class="graph-world" id="graphWorld"></div><div class="graph-key"><span>─ Delega</span><span>┄ Dipendenza</span><span>··· Messaggio</span></div><svg class="mini" viewBox="0 0 930 540" aria-label="Panoramica del diagramma" id="minimap"></svg></div>${graph.split ? `<div class="split-preview"><div class="row"><b class="small grow truncate">${esc(s.selectedFile)}</b><button data-action="split" aria-label="Chiudi affiancamento">${icon('x')}</button></div><pre>${esc(bodies[s.selectedFile] || '// Anteprima demo')}</pre></div>` : ''}</div><div class="timeline"><button class="btn" data-action="event-next" title="Avanza di un evento nella simulazione">Evento +</button><span>${graph.time === 4 ? 'ORA' : 'T' + graph.time}</span><input type="range" id="replay" min="0" max="4" value="${graph.time}" step="1" aria-label="Timeline della simulazione"><span class="muted">Replay demo</span></div></div>`; }
function drawGraph() {
    const host = $('#graphWorld');
    if (!host)
        return;
    const s = store.get(), list = graphAgents();
    const visible = new Set(list.map(a => a.id));
    let edges = '';
    for (const a of list) {
        if (a.parent && visible.has(a.parent)) {
            const p = agents.find(x => x.id === a.parent);
            edges += `<path d="M${p.pos[0] + 107},${p.pos[1] + 124} C${p.pos[0] + 107},${p.pos[1] + 172} ${a.pos[0] + 107},${a.pos[1] - 38} ${a.pos[0] + 107},${a.pos[1]}"/>`;
        }
    }
    if (visible.has('audit') && visible.has('fix'))
        edges += `<path d="M264,278 L358,278" stroke-dasharray="5 5"/>`;
    if (visible.has('ux') && visible.has('qa'))
        edges += `<path d="M774,340 C774,380 312,380 312,410" stroke-dasharray="2 6"/>`;
    host.innerHTML = `<svg viewBox="0 0 930 540" fill="none" stroke="var(--talos-secondary)" stroke-width="1.3">${edges}</svg>${list.map(a => `<article class="node ${a.id === s.selectedAgent ? 'selected' : ''}" style="left:${a.pos[0]}px;top:${a.pos[1]}px" data-agent="${a.id}" tabindex="0" role="button" aria-label="Apri dettaglio ${esc(a.name)}"><div class="row"><h3 class="grow">${esc(a.name)}</h3>${a.status === 'error' ? '<span class="danger">!</span>' : `<span class="dot ${statuses[a.status][1] === 'accent' ? 'warn' : statuses[a.status][1]}"></span>`}</div><p>${esc(a.role)}</p><div class="row">${stateBadge(a)}<span class="grow"></span><span class="small muted">${a.duration}</span></div><div class="row node-foot"><span>${esc(a.tool)} · demo</span>${agents.some(x => x.parent === a.id) ? `<button data-action="collapse-branch" data-id="${a.id}" aria-expanded="${!graph.collapsed.has(a.id)}" title="Espandi o collassa i figli">${graph.collapsed.has(a.id) ? 'Espandi' : 'Collassa'} ${agents.filter(x => x.parent === a.id).length}</button>` : ''}</div></article>`).join('')}${!list.length ? '<div class="empty" style="width:500px"><h3>Nessun agente per questi filtri</h3><button class="btn" data-action="graph-clear">Azzera filtri</button></div>' : ''}`;
    $('#minimap').innerHTML = `<g fill="var(--talos-panel-soft)" stroke="var(--talos-accent)">${list.map(a => `<rect x="${a.pos[0]}" y="${a.pos[1]}" width="214" height="124" rx="12"/>`).join('')}</g>`;
    transformGraph();
}
function transformGraph() { const w = $('#graphWorld'); if (w)
    w.style.transform = `translate(${graph.x}px,${graph.y}px) scale(${graph.zoom})`; if ($('#zoomLabel'))
    $('#zoomLabel').textContent = Math.round(graph.zoom * 100) + '%'; }
function fitGraph() { const c = $('#graphCanvas'); if (!c)
    return; const list = graphAgents(); if (!list.length)
    return; const minX = Math.min(...list.map(a => a.pos[0])), minY = Math.min(...list.map(a => a.pos[1])); const w = Math.max(...list.map(a => a.pos[0] + 214)) - minX, h = Math.max(...list.map(a => a.pos[1] + 125)) - minY; graph.zoom = Math.min(1.1, Math.max(.25, Math.min((c.clientWidth - 40) / w, (c.clientHeight - 70) / h))); graph.x = (c.clientWidth - w * graph.zoom) / 2 - minX * graph.zoom; graph.y = 16 - minY * graph.zoom; transformGraph(); }
function reviewView() { const s = store.get(); const applied = s.reviewStatus === 'applied', discarded = s.reviewStatus === 'discarded'; return `<div class="workspace-view"><div class="view-head"><div class="grow"><div class="eyebrow" style="margin-bottom:6px">Proposta in area isolata · demo</div><h2>Revisione modifiche</h2><p>Navigazione · guardia della conversazione figlia</p></div>${badge(applied ? 'Integrata nella demo' : discarded ? 'Scartata' : s.conflict ? 'Conflitto' : 'Da approvare', applied ? 'good' : s.conflict ? 'danger' : 'warn')}</div><div class="toolbar"><button class="primary" data-action="apply" ${s.conflict || applied || discarded ? 'disabled' : ''}>Integra nella demo</button><button class="btn" data-action="revision">Richiedi revisione</button><button class="danger" data-action="discard" ${applied || discarded ? 'disabled' : ''}>Scarta</button><span class="grow"></span><button data-action="file-agent" data-id="fix" title="Apri l’agente responsabile">${icon('branch')}</button></div><div class="provenance"><div class="row wrap"><span>Agente <b>Navigazione</b></span><span>·</span><span class="mono small">isolata/demo-sidebar</span><span class="grow"></span><label class="row small"><input type="checkbox" id="conflictToggle" ${s.conflict ? 'checked' : ''} ${applied ? 'disabled' : ''}>Simula conflitto</label></div><p class="muted" style="margin-top:7px">Motivo: il dettaglio separato non deve restare visibile sopra File, Context o Processi. ${s.revision ? 'Revisione richiesta: ' + s.revision + '.' : ''}</p>${s.conflict ? '<div class="notice" style="margin-top:10px;color:var(--talos-danger);border-color:var(--talos-danger-border)">Il file di destinazione è cambiato. Integrazione bloccata: nessuna sovrascrittura silenziosa. Disattiva il conflitto simulato per continuare.</div>' : ''}</div><div class="review-layout"><div class="review-files"><span class="eyebrow" style="padding:8px;display:block">2 file demo</span><button class="${s.selectedFile === 'main.css' ? '' : 'active'}" data-action="review-file" data-id="inspector-tab-visibility.css">inspector-tab-visibility.css<div class="small good">+${reviewSource.trimEnd().split('\n').length}</div></button><button class="${s.selectedFile === 'main.css' ? 'active' : ''}" data-action="review-file" data-id="main.css">main.css<div class="small good">+1</div></button></div><div class="stack" style="min-width:0;gap:0"><div class="diff" tabindex="0" aria-label="Differenze proposte, dati demo">${s.selectedFile === 'main.css' ? `<div>  @import './mockup-animazioni.css';</div><div class="add">+ @import './inspector-tab-visibility.css';</div>` : reviewSource.trimEnd().split('\n').map(line => '<div class="add">+ ' + esc(line) + '</div>').join('')}</div><div class="checks"><span class="good">✓ Verifiche della fixture</span><span>Esiti dimostrativi · non CI</span><span class="grow"></span><span>${s.conflict ? '1 conflitto' : 'Nessun conflitto demo'}</span></div></div></div><div class="rail-foot"><p class="small muted">${applied ? 'La proposta è segnata come integrata soltanto nella memoria del browser.' : discarded ? 'La proposta è stata scartata nella simulazione. Richiedi una revisione per ripartire.' : 'La conferma riguarda la demo. Nessun file reale, commit o processo viene modificato da questa pagina.'}</p></div></div>`; }
